1	// LG3: cache-file helpers for the engine reset-state baseline -- the
2	// hybrid_state_v1 drained from a freshly reset, halted hart that the
3	// liveness gate (ResumeDriver::set_reset_baseline) compares restores
4	// against. Pure path/IO helpers; the capture itself lives in the simulator
5	// (it needs the DMI bus and the scratch-page lifts).
6	
7	#pragma once
8	
9	#include "hybrid/state_abi.h"
10	#include "hybrid/state_loader.hpp"
11	
12	#include <cstdint>
13	#include <filesystem>
14	#include <fstream>
15	#include <optional>
16	#include <string>
17	#include <string_view>
18	
19	namespace hybrid {
20	
21	// <engine>-<version>-<binary mtime>-<binary size>-<elf mtime>-<elf size>.bin
22	// The binary identity invalidates the cache on rebuild. The ELF identity is
23	// part of the key because the hart free-runs a few workload instructions
24	// between reset and the DMI halt, so the halted state is deterministic
25	// per-(engine build, ELF), not per-engine.
26	inline auto reset_baseline_file_name(std::string_view engine,
27	                                     std::string_view version,
28	                                     uint64_t bin_mtime, uint64_t bin_size,
29	                                     uint64_t elf_mtime, uint64_t elf_size)
30	  -> std::string
31	{
32	  return std::string{engine} + "-" + std::string{version} + "-"
33	       + std::to_string(bin_mtime) + "-" + std::to_string(bin_size) + "-"
34	       + std::to_string(elf_mtime) + "-" + std::to_string(elf_size) + ".bin";
35	}
36	
37	// $XDG_CACHE_HOME/andesim, else $HOME/.cache/andesim, else "" (disabled).
38	// Env values are injected so the resolution is unit-testable.
39	inline auto reset_baseline_cache_root(const char* xdg_cache_home,
40	                                      const char* home)
41	  -> std::filesystem::path
42	{
43	  if (xdg_cache_home && *xdg_cache_home)
44	    return std::filesystem::path{xdg_cache_home} / "andesim";
45	  if (home && *home)
46	    return std::filesystem::path{home} / ".cache" / "andesim";
47	  return {};
48	}
49	
50	// nullopt on any load_state failure (missing / short / bad magic / wrong
51	// version) -- a stale or corrupt cache entry means "capture again", never
52	// an aborted run.
53	inline auto try_load_reset_baseline(const std::filesystem::path& p)
54	  -> std::optional<hybrid_state_v1>
55	{
56	  try {
57	    return load_state(p.string());
58	  } catch (const std::exception&) {
59	    return std::nullopt;
60	  }
61	}
62	
63	// Create parent directories and write the raw struct. False on any failure
64	// -- the cache is an optimization, never a reason to abort a run.
65	inline auto save_reset_baseline(const std::filesystem::path& p,
66	                                const hybrid_state_v1& s) -> bool
67	{
68	  std::error_code ec;
69	  if (p.has_parent_path())
70	    std::filesystem::create_directories(p.parent_path(), ec);
71	  std::ofstream f(p, std::ios::binary | std::ios::trunc);
72	  if (!f) return false;
73	  f.write(reinterpret_cast<const char*>(&s), sizeof s);
74	  return static_cast<bool>(f);
75	}
76	
77	}  // namespace hybrid
