190	  ~Simulator() { trace_.close(); }
191	
192	  void init_debug_port(const uint16_t port = 9104)
193	  {
194	    dtm_debug = true;
195	    dtm.init_port(port);
196	    spdlog::info("waiting for debugger connection");
197	  }
198	
199	  // Caller invariant: the CPU must already be out of reset.
200	  //
201	  // baseline_cache (LG3): path to this (engine build, ELF)'s reset-state
202	  // baseline; empty disables the liveness gate (transport-everything). On a
203	  // cache miss the baseline is captured HERE: the hart is freshly reset and
204	  // the capture drain halts it exactly where resume() would, so the drained
205	  // values ARE what the gate must compare restores against. Capture runs
206	  // BEFORE the scratch stagings below -- its drain sweeps dump reset
207	  // registers through the same scratch page the stagings fill.
208	  void apply_resume_from_qemu(const std::string& path,
209	                              const std::string& baseline_cache = {})
210	  {
211	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
212	      bus{platform.dmi, platform.clk.period()};
213	    hybrid_input_state_ = hybrid::load_state(path);
214	
215	    std::optional<hybrid_state_v1> baseline{};
216	    bool baseline_captured = false;
217	    if (!baseline_cache.empty()) {
218	      baseline = hybrid::try_load_reset_baseline(baseline_cache);
219	      // Stale-shape insurance: a cache whose flags/vlenb no longer cover the
220	      // incoming state was captured under a different engine/QEMU pairing.
221	      if (baseline
222	          && ((baseline->flags & hybrid_input_state_->flags)
223	                != hybrid_input_state_->flags
224	              || baseline->vlenb != hybrid_input_state_->vlenb))
225	        baseline.reset();
226	      if (!baseline) {
227	        baseline = capture_reset_baseline(bus, *hybrid_input_state_);
228	        baseline_captured = true;
229	        if (!hybrid::save_reset_baseline(baseline_cache, *baseline))
230	          spdlog::warn("hybrid: cannot save reset baseline to {}",
231	                       baseline_cache);
232	      }
233	      spdlog::info("hybrid: reset baseline {} ({})",
234	                   baseline_captured
235	                     ? "captured -- one-time cost per engine build + ELF"
236	                     : "cache hit",
237	                   baseline_cache);
238	    }
239	
240	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
241	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
242	    // this region to repopulate v0..v31, so the bytes must be in place first.
243	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
244	    // dropping V state.
245	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
246	      hybrid::stage_v_to_scratch(*hybrid_input_state_,
247	                                 platform.main_memory.data);
248	    }
249	    // GPR block-load: stage x1..x31 into the scratch page so the resume
250	    // ld-sweep repopulates them in ~6 DM round-trips instead of 31 abstract
251	    // writes. Host memcpy is free. Gate on gpr_scratch_fits -- the same
252	    // condition ResumeDriver uses -- so when the V data fills the page we skip
253	    // staging (the abstract-write fallback runs) and never clobber v30/v31.
254	    if (hybrid::gpr_scratch_fits(hybrid_input_state_->vlenb))
255	      hybrid::stage_gpr_to_scratch(*hybrid_input_state_,
256	                                   platform.main_memory.data);
257	    // FPR block-load: stage f0..f31 just below the GPR block so the resume
258	    // fld-sweep repopulates them in ~6 DM round-trips instead of 32 abstract
259	    // writes. Gate on the FP flag and fpr_scratch_fits (tighter than the GPR
260	    // gate -- the FPR block sits lower in the page), so a full V page skips
261	    // staging and the abstract-write fallback runs.
262	    if ((hybrid_input_state_->flags & HYBRID_FLAG_FP) != 0u
263	        && hybrid::fpr_scratch_fits(hybrid_input_state_->vlenb))
264	      hybrid::stage_fpr_to_scratch(*hybrid_input_state_,
265	                                   platform.main_memory.data);
266	    // NOTE: the RESTORE csr_sweep stays OFF. A csrrw to a caps-supported but
267	    // read-only / WARL-illegal CSR raises cmderr in the Program Buffer, and a
268	    // batched sweep cannot tolerate a mid-batch fault the way the abstract path's
269	    // per-CSR clear_cmderr does. Restoring those CSRs is a no-op anyway (can't
270	    // write a read-only CSR), so restore keeps the abstract-tolerant path until a
271	    // per-CSR writability model can gate the sweep. The DRAIN sweep IS on (csrr
272	    // reads never fault for a readable CSR) -- see set_block_store_drain.
273	    hybrid::ResumeDriver driver(bus, v_scratch_gpa(),
274	                                hybrid::andes_caps_from_config());
275	    driver.set_gpr_block_load(true);
276	    driver.set_fpr_block_load(true);
277	    // LG3: on a capture run the capture drain's V dump sweep clobbered
278	    // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
279	    if (baseline)
280	      driver.set_reset_baseline(*baseline,
281	                                /*v_cfg_at_reset=*/!baseline_captured);
282	    driver.resume(*hybrid_input_state_);
283	    if (baseline)
284	      spdlog::info("hybrid: liveness gate elided {} register restores",
285	                   driver.baseline_skip_count());
286	  }
287	
288	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
289	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
290	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
291	  //
292	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
293	  // mode) and the ELF scan is skipped: the binary need not contain a magic
294	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
295	  // run -- callers pass exactly one form.
296	  void enable_hybrid_handoff(const std::string& elf_path,
297	                             const std::string& state_out_path,
298	                             std::optional<uint64_t> exit_pc = std::nullopt,
299	                             bool drain_minimal = false)
300	  {
301	    hybrid::CsrTrigger trigger;
302	    if (exit_pc) {
303	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
304	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
305	    } else {
306	      auto elf = LIEF::ELF::Parser::parse(elf_path);
307	      if (!elf)
308	        throw std::runtime_error(
309	          "enable_hybrid_handoff: failed to parse " + elf_path);
310	      for (const auto& seg: elf->segments()) {
311	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
312	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
313	        const auto content = seg.content();
314	        const std::span<const uint8_t> bytes{content.data(), content.size()};
315	        trigger.scan_buffer(bytes, seg.virtual_address());
316	      }
317	    }
318	
319	    hybrid_dmi_bus_ = std::make_unique<
320	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
321	                            PLATFORM::dmi_data_width>>(platform.dmi,
322	                                                       platform.clk.period());
323	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
324	                            v_scratch_gpa(), hybrid::andes_caps_from_config());
325	    if (hybrid_input_state_)
326	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
327	    hybrid_handoff_->set_minimal_drain(drain_minimal);
328	    hybrid_handoff_->set_block_store_drain(true);
329	    hybrid_drain_minimal_ = drain_minimal;
330	    hybrid_state_path_ = state_out_path;
331	  }
332	
333	private:
334	  // L26: the GUEST address of the V-register transport page -- the top page of
335	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
336	  // so this sits just past the program's declared RAM and never collides with
337	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
338	  auto v_scratch_gpa() const -> uint64_t
339	  {
340	    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
341	                                 platform.main_memory.data.size());
342	  }
343	
344	  // LG3: drain the freshly reset, just-halted hart into a baseline the
345	  // liveness gate compares restores against. The probe carries the incoming
346	  // state's flags/vlenb so drain_with_passthrough reads exactly the blocks
347	  // the gate will compare (it is flag-driven); every probe field it does not
348	  // re-read stays zero, matching what an absent block compares against.
349	  auto capture_reset_baseline(
350	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
351	                          PLATFORM::dmi_data_width>& bus,
352	    const hybrid_state_v1& input) -> hybrid_state_v1
353	  {
354	    hybrid::StateDrain drain(bus, v_scratch_gpa(),
355	                             hybrid::andes_caps_from_config());
356	    drain.set_gpr_block_store(true);
357	    drain.set_fpr_block_store(true);
358	    drain.set_csr_sweep(true);
359	    // At reset mstatus.FS/VS are Off, so the capture's fsd/vse8 sweeps (and
360	    // the FPR/V CSR abstract reads) would raise illegal instruction
361	    // (cmderr=3). Halt and enable them first, exactly like resume() does
362	    // before its FPR/V writes. Safe to clobber: mstatus is never re-read by
363	    // a drain nor gated by the baseline, and resume() rewrites it whenever
364	    // the FP/V flags are set -- the only case this branch runs.
365	    if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
366	      using RD = hybrid::ResumeDriver;
367	      bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
368	      bus.write(RD::kDmcontrol,
369	                RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
370	      hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
371	                             "reset-baseline capture halt");
372	      const uint64_t mstatus = hybrid::read_register_64(
373	        bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
374	      uint64_t enable = mstatus;
375	      if ((input.flags & HYBRID_FLAG_FP)
376	          && (enable & RD::kMstatusFsMask) == 0)
377	        enable |= RD::kMstatusFsInitial;
378	      if ((input.flags & HYBRID_FLAG_V)
379	          && (enable & RD::kMstatusVsMask) == 0)
380	        enable |= RD::kMstatusVsInitial;
381	      if (enable != mstatus)
382	        hybrid::write_register_abstract(
383	          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
384	    }
385	    hybrid_state_v1 probe{};
386	    probe.magic = HYBRID_STATE_MAGIC;
387	    probe.version = HYBRID_STATE_VERSION;
388	    probe.flags = input.flags;
389	    probe.vlenb = input.vlenb;
390	    auto baseline = drain.drain_with_passthrough(probe);
391	    lift_scratch_blocks(baseline, /*csr_swept=*/true);
392	    return baseline;
393	  }
394	
395	  // Lift the scratch-page transports into `state` (dual of the resume
396	  // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
397	  // state carries vsim's actual V values, not QEMU 1's stale snapshot -- and
398	  // the drain sd/fsd block-store sweeps (x1..x30 / f0..f31) into the GPR/FPR
399	  // slots. Gated on the SAME fits conditions StateDrain used to pick
400	  // sweep-vs-abstract: when the V page is full it read the registers via
401	  // Abstract Commands and populated the state directly, so lifting stale
402	  // scratch would clobber correct values. x31 (the GPR sweep base) was
403	  // captured via abstract read inside the drain, so only x1..x30 lift.
404	  // Shared by the exit drain and the reset-baseline capture.
405	  //
406	  // csr_swept: whether the drain's Andes+M-ext csrr+sd sweep ran. False on a
407	  // minimal drain (drain_counters_only never sweeps, and nothing stages the
408	  // CSR region at resume -- the restore sweep is off -- so its bytes are
409	  // meaningless and lifting them would corrupt the passthrough values).
410	  void lift_scratch_blocks(hybrid_state_v1& state, bool csr_swept)
411	  {
412	    const std::span<const uint8_t> ram{platform.main_memory.data.data(),
413	                                       platform.main_memory.data.size()};
414	    if ((state.flags & HYBRID_FLAG_V) != 0u)
415	      hybrid::read_v_from_scratch(state, ram);
416	    if (hybrid::gpr_scratch_fits(state.vlenb))
417	      hybrid::read_gpr_from_scratch(state, ram, 30);
418	    if ((state.flags & HYBRID_FLAG_FP) != 0u
419	        && hybrid::fpr_scratch_fits(state.vlenb))
