421	    if (csr_swept
422	        && (state.flags & (HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT)) != 0u
423	        && hybrid::csr_scratch_fits(state.vlenb))
424	      hybrid::read_csr_from_scratch(state, ram,
425	                                    hybrid::andes_caps_from_config());
